diff:
--- a/rtl/token_bucket.v
+++ b/rtl/token_bucket.v
@@ -34,8 +34,10 @@
     // Refill timer: one token every `rate` cycles
     // ------------------------------------------------------------------
-    assign refill = (timer == rate - 1'b1);
+    assign refill = (rate != {RW{1'b0}}) && (timer >= rate - 1'b1);

     always @(posedge clk or negedge rst_n) begin
         if (!rst_n)
+            timer <= {RW{1'b0}};
+        else if (rate == {RW{1'b0}})
             timer <= {RW{1'b0}};
         else if (refill)
@@ -53,9 +55,9 @@

     always @(*) begin
-        tokens_nx = tokens;
-        if (refill && tokens_nx != CAP_V)
-            tokens_nx = tokens_nx + 1'b1;
-        if (grant)
-            tokens_nx = tokens_nx - 1'b1;
+        reg [TW:0] sum;
+        sum = {1'b0, tokens} - (grant ? 1'b1 : 1'b0) + (refill ? 1'b1 : 1'b0);
+        if (sum > {1'b0, CAP_V})
+            sum = {1'b0, CAP_V};
+        tokens_nx = sum[TW-1:0];
     end
